      resultDiv.textContent = t("ai.collecting", "\u0E01\u0E33\u0E25\u0E31\u0E07\u0E23\u0E27\u0E1A\u0E23\u0E27\u0E21\u0E02\u0E49\u0E2D\u0E21\u0E39\u0E25\u2026");
      box2.append(resultDiv);
