      const { getAIClient: getAIClient2 } = await Promise.resolve().then(() => (init_ai_bridge(), ai_bridge_exports));
      const res = await checkConsistency2(entityPath, { client: getAIClient2(), entity, scenes });
      resultDiv.textContent = "";
