  async function invertRole(role) {
    if (!INV_C.m) {
      INV_C.m = {};
      try {
        const d = await fetch("inverse_roles.json").then((r) => r.json());
        for (const [a, b] of d.pairs || []) {
          INV_C.m[a] = b;
          if (!(b in INV_C.m)) INV_C.m[b] = a;
        }
        if (d.categories && typeof d.categories === "object") INV_C.cat = d.categories;
      } catch {
      }
    }
    return INV_C.m[role] || role;
  }
  async function warmInverse() {
    await invertRole("");
  }
