  async function findEntityInScenes(entityPath, name5, x, y) {
    setStatus(t("ui.app.busySearchSceneMention") + name5 + "\u201D \u2026");
    await ensureAutoLink();
    const links = (getBacklinksFor(entityPath) || []).slice().sort((a, b) => (b.count || 0) - (a.count || 0));
    if (!links.length) {
      setStatus(t("ui.app.notHasSceneMention") + name5 + "\u201D");
      return links;
    }
    const items = links.map((l) => ({
      label: iconHtml("file", 14) + " " + (l.title || l.sceneId) + '  <span class="dim">' + (l.count || 1) + "\xD7" + (l.via ? " \xB7 " + l.via : "") + "</span>",
      click: async () => {
        const hit = await findScenePath(state.root, l.sceneId);
        if (hit && await kapi.exists(hit.path)) openScene(hit.path, hit.title);
        else setStatus(t("ui.app.notFoundFileScene") + (l.title || l.sceneId));
      }
    }));
    items.unshift({ label: tf("ui.app.sceneMention", links.length, name5), disabled: true }, "-");
    popupMenu(typeof x === "number" ? x : 80, typeof y === "number" ? y : 80, items);
    setStatus(tf("ui.app.foundSceneMention", links.length, name5));
    return links;
  }
