    try {
      for (const e of await listEntities(state.root)) {
        const rel = (await kapi.relative(state.root, e.path)).replace(/\\/g, "/");
        items.push({ path: rel, title: e.name, label: `\u{1F464} Wiki / ${e.cat} / ${e.name}` });
      }
    } catch {
    }
