  async function sceneCtx(file) {
    const t3 = file ? { file } : state.active;
    if (!t3 || !t3.file || !/\.md$/i.test(t3.file) || !/[\\/]Chapters[\\/]/.test(t3.file)) return null;
    const dPath = t3.file.replace(/[\\/]Chapters[\\/].*$/, "");
    try {
      const scenes = await kapi.readJson(await kapi.join(dPath, "scenes.json"));
      const draft = await kapi.readJson(await kapi.join(dPath, "draft.json"));
      const fname = t3.file.split(/[\\/]/).pop();
      for (const ch of draft.chapters || []) {
        const row2 = ((scenes.chapters || {})[ch.guid] || []).find((s) => s.fileName === fname);
        if (row2) return { dPath, ch, row: row2 };
      }
    } catch (e) {
      log("warn", "sceneCtx failed", e);
    }
    return null;
  }
  async function syncSceneMetaFromFiles(dPath) {
    const dir = dPath || (await sceneCtx())?.dPath;
    if (!dir) {
      setStatus(t("ui.app.openSceneDraftBeforeProps"));
      return 0;
    }
    const sf = await kapi.join(dir, "scenes.json");
    const d = await kapi.readJson(sf);
    const draft = await kapi.readJson(await kapi.join(dir, "draft.json"));
    let n2 = 0;
    for (const ch of draft.chapters || []) {
      for (const row2 of (d.chapters || {})[ch.guid] || []) {
        const file = await kapi.join(dir, "Chapters", ch.folderName, row2.fileName);
        const m = await readSceneMeta(file, row2);
        for (const k of SCENE_HEAVY_KEYS) {
          const before = JSON.stringify(row2[k] ?? null), after = JSON.stringify(m[k] ?? null);
          if (before !== after) {
            row2[k] = m[k];
            n2++;
          }
        }
      }
    }
    if (n2) {
      await kapi.writeFile(sf, JSON.stringify(d, null, 2));
      await buildTree2();
    }
    setStatus(n2 ? tf("ui.app.propsSceneFileMd", n2) : t("ui.app.propsSceneAtFile"));
    return n2;
  }
  async function readLangTable(lang) {
    try {
      const csv = await kapi.langRead(lang, state.root || "");
      if (csv && csv.trim()) return csvToTable(csv);
    } catch {
    }
    return {};
  }
  async function exportLanguageCsv(target) {
    const th = await readLangTable("th");
    const code3 = target || (i18n.lang && i18n.lang !== "th" ? i18n.lang : "en");
    const dst = await readLangTable(code3);
    if (!Object.keys(th).length && !Object.keys(dst).length) {
      setStatus(tf("ui.app.notFoundFileLang", code3));
      return false;
    }
    const keys4 = [.../* @__PURE__ */ new Set([...Object.keys(th), ...Object.keys(dst)])].filter((k) => !k.startsWith("meta."));
    const q = (v2) => {
      const x = v2 == null ? "" : String(v2);
      return /[",\r\n]/.test(x) ? '"' + x.replace(/"/g, '""') + '"' : x;
    };
    const rows = ["key,th," + code3];
    for (const k of keys4) rows.push(q(k) + "," + q(th[k] ?? k) + "," + q(dst[k] || ""));
    const csv = "\uFEFF" + rows.join("\r\n") + "\r\n";
    const dest = await kapi.saveAsDialog("k2_" + code3 + ".csv", "csv");
    if (!dest) return false;
    await kapi.writeFile(dest, csv);
    setStatus(tf("ui.app.exportTableWordDone", keys4.length) + dest);
    log("info", "i18n-csv: export " + keys4.length + " keys \u2192 " + dest);
    return true;
  }
  async function importLanguageCsv(srcPath) {
    if (!state.root) {
      setStatus(t("ui.app.openProjectBeforeImport"));
      return false;
    }
    const src2 = srcPath || await kapi.openFileDialog("csv");
    if (!src2) return false;
    let text = "";
    try {
      text = await kapi.readFile(src2);
    } catch (e) {
      setStatus(t("ui.app.readFileCSVCant") + e.message);
      return false;
    }
    const rows = parseCsv(String(text).replace(/\ufeff/g, ""));
    if (!rows.length) {
      setStatus(t("ui.app.notFoundKeyFile"));
      return false;
    }
    const head2 = rows[0].map((c) => String(c).trim().toLowerCase());
    const hasHead = head2[0] === "key";
    const cols = [];
    if (hasHead) {
      for (let i5 = 1; i5 < head2.length; i5++) {
        const c = head2[i5];
        if (c === "text" || c === "value") cols.push([i5, i18n.lang || "th"]);
        else if (/^[a-z]{2,3}(-[a-z0-9]{2,8})?$/i.test(c)) cols.push([i5, c.split("-")[0] + (c.includes("-") ? "-" + c.split("-")[1].toUpperCase() : "")]);
      }
    }
    if (!cols.length) cols.push([1, i18n.lang || "th"]);
    const body = hasHead ? rows.slice(1) : rows;
    const res = { keys: [], skipped: 0, langs: [], added: 0, changed: 0 };
    const dir = await kapi.join(state.root, "languages");
    await kapi.mkdir(dir);
    for (const [ci, lang] of cols) {
      const patch = {};
      for (const r of body) {
        const k = r[0] == null ? "" : String(r[0]);
        if (!k || k.startsWith("#")) {
          if (ci === cols[0][0]) res.skipped++;
          continue;
        }
        if (ci === cols[0][0] && !res.keys.includes(k)) res.keys.push(k);
        const v2 = r[ci] == null ? "" : String(r[ci]);
        if (v2 !== "") patch[k] = v2;
      }
      if (!Object.keys(patch).length) continue;
      const file = await kapi.join(dir, langFileName(lang));
      let base3 = {};
      try {
        if (await kapi.exists(file)) base3 = csvToTable(await kapi.readFile(file));
      } catch {
      }
      for (const k of Object.keys(patch)) {
        if (!(k in base3)) res.added++;
        else if (base3[k] !== patch[k]) res.changed++;
        base3[k] = patch[k];
      }
      base3["meta.code"] = lang;
      base3["meta.nativeName"] = base3["meta.nativeName"] || fallbackLangName(lang);
      await kapi.writeFile(file, tableToCsv(base3));
      res.langs.push(lang);
    }
    if (!res.langs.length) {
      setStatus(t("ui.app.notFoundKeyFile"));
      return false;
    }
    try {
      await loadLanguage(i18n.lang, state.root);
      applyDataI18n();
      updateToolbarTitles();
    } catch {
    }
    setStatus(tf("ui.app.importKeyLangAdd", res.keys.length, res.langs.join(", "), res.added + res.changed));
    log("info", "i18n-csv: import " + JSON.stringify(res));
    return res;
  }
